class Solution:
    def countPoints(self, points, queries):
        res = []
        for x, y, r in queries:
            r2 = r * r
            cnt = 0
            for px, py in points:
                if (px - x) ** 2 + (py - y) ** 2 <= r2:
                    cnt += 1
            res.append(cnt)
        return res

