class Solution {
public:
    vector<int> countPoints(vector<vector<int>>& points, vector<vector<int>>& queries) {
        vector<int> res;
        res.reserve(queries.size());
        for (auto& q : queries) {
            long long r2 = (long long)q[2] * q[2];
            int cnt = 0;
            for (auto& p : points) {
                long long dx = p[0] - q[0], dy = p[1] - q[1];
                if (dx * dx + dy * dy <= r2) cnt++;
            }
            res.push_back(cnt);
        }
        return res;
    }
};

