import math


class Solution:
    def countPoints(self, points, queries):
        C = 501
        row = [[0] * (C + 1) for _ in range(C)]
        for x, y in points:
            row[y][x + 1] += 1
        for y in range(C):
            for x in range(1, C + 1):
                row[y][x] += row[y][x - 1]

        def span(y, lo, hi):
            lo = max(lo, 0)
            hi = min(hi, 500)
            if lo > hi:
                return 0
            return row[y][hi + 1] - row[y][lo]

        res = []
        for cx, cy, r in queries:
            total = 0
            r2 = r * r
            for y in range(max(0, cy - r), min(500, cy + r) + 1):
                dy = y - cy
                a = math.isqrt(r2 - dy * dy)
                total += span(y, cx - a, cx + a)
            res.append(total)
        return res

