class Solution {
public:
    vector<int> countPoints(vector<vector<int>>& points, vector<vector<int>>& queries) {
        const int C = 501;
        vector<vector<int>> row(C, vector<int>(C + 1, 0));
        for (auto& p : points) row[p[1]][p[0] + 1]++;
        for (int y = 0; y < C; y++)
            for (int x = 1; x <= C; x++)
                row[y][x] += row[y][x - 1];

        vector<int> res;
        res.reserve(queries.size());
        for (auto& q : queries) {
            long long total = 0, r2 = (long long)q[2] * q[2];
            int yLo = max(0, q[1] - q[2]), yHi = min(500, q[1] + q[2]);
            for (int y = yLo; y <= yHi; y++) {
                long long rem = r2 - (long long)(y - q[1]) * (y - q[1]);
                long long a = (long long)sqrt((double)rem);
                while ((a + 1) * (a + 1) <= rem) a++;
                while (a * a > rem) a--;
                int lo = max(0, q[0] - (int)a), hi = min(500, q[0] + (int)a);
                if (lo > hi) continue;
                total += row[y][hi + 1] - row[y][lo];
            }
            res.push_back((int)total);
        }
        return res;
    }
};

