        int[] res = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int[] q = queries[qi];
            long total = 0, r2 = (long) q[2] * q[2];
            int yLo = Math.max(0, q[1] - q[2]), yHi = Math.min(500, q[1] + q[2]);
            for (int y = yLo; y <= yHi; y++) {
                long rem = r2 - (long) (y - q[1]) * (y - q[1]);
                long a = (long) Math.sqrt(rem);
                while ((a + 1) * (a + 1) <= rem) a++;
                while (a * a > rem) a--;
                int lo = Math.max(0, q[0] - (int) a), hi = Math.min(500, q[0] + (int) a);
                if (lo > hi) continue;
                total += row[y][hi + 1] - row[y][lo];
            }
            res[qi] = (int) total;
        }
        return res;
    }
}

