var countPoints = function(points, queries) {
    const C = 501;
    const row = Array.from({length: C}, () => new Array(C + 1).fill(0));
    for (const [x, y] of points) row[y][x + 1]++;
    for (let y = 0; y < C; y++)
        for (let x = 1; x <= C; x++) row[y][x] += row[y][x - 1];

    const span = (y, lo, hi) => {
        lo = Math.max(lo, 0);
        hi = Math.min(hi, 500);
        return lo > hi ? 0 : row[y][hi + 1] - row[y][lo];
    };

    return queries.map(([cx, cy, r]) => {
        let total = 0;
        const r2 = r * r;
        const yLo = Math.max(0, cy - r), yHi = Math.min(500, cy + r);
        for (let y = yLo; y <= yHi; y++) {
            const rem = r2 - (y - cy) * (y - cy);
            let a = Math.floor(Math.sqrt(rem));
            while ((a + 1) * (a + 1) <= rem) a++;
            while (a * a > rem) a--;
            total += span(y, cx - a, cx + a);
        }
        return total;
    });
};
